import{_ as t,o as h,c as i,a2 as g}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"Quy tắc Đi qua Mặt phẳng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/81-位面穿梭规则.md","filePath":"vi/81-位面穿梭规则.md","lastUpdated":1789183869000}'),a={name:"vi/81-位面穿梭规则.md"};function c(u,n,p,o,l,m){return h(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="quy-tac-đi-qua-mat-phang" tabindex="-1">Quy tắc Đi qua Mặt phẳng <a class="header-anchor" href="#quy-tac-đi-qua-mat-phang" aria-label="Permalink to &quot;Quy tắc Đi qua Mặt phẳng&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>81</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Đi qua mặt phẳng, giấy phép đi qua, ngưỡng năng lượng, hiệu chỉnh neo, phòng ngừa ô nhiễm</td></tr></tbody></table><h2 id="_1-vi-tri-phap-ly-cua-hanh-đong-đi-qua" tabindex="-1">1. Vị trí Pháp lý của Hành động Đi qua <a class="header-anchor" href="#_1-vi-tri-phap-ly-cua-hanh-đong-đi-qua" aria-label="Permalink to &quot;1. Vị trí Pháp lý của Hành động Đi qua&quot;">​</a></h2><p>Đi qua mặt phẳng đề cập đến hành động của cá nhân hoặc nhóm sinh vật, thông qua phương tiện công nghệ hoặc năng lực tu luyện, vượt qua rào cản luật pháp từ một mặt phẳng để vào mặt phẳng khác. Trong khuôn khổ pháp lý của văn minh cộng sinh neo, đi qua mặt phẳng được phân loại là &quot;hành động đặc biệt có rủi ro cao&quot; và phải chịu sự quản lý giấy phép nghiêm ngặt cũng như giám sát quy trình. Điều 47 &quot;Hiến pháp Cộng sinh&quot; quy định rõ ràng: &quot;Không tổ chức hay cá nhân nào được tự ý thực hiện đi qua liên mặt phẳng mà không có giấy phép, cũng không được sử dụng đi qua mặt phẳng để thực hiện các hoạt động cướp bóc, can thiệp hoặc gây ô nhiễm đối với văn minh mặt phẳng khác.&quot;</p><p>Lý do cơ bản tại sao đi qua mặt phẳng đòi hỏi kiểm soát nghiêm ngặt là bản thân hành động đi qua có thể gây ra nhiều tác động lên mặt phẳng mục tiêu: xáo trộn luật pháp, tiêm năng lượng, ô nhiễm ý thức, xâm nhập vi sinh vật và can thiệp văn hóa, giữa những thứ khác. Những tác động này, ở mức độ nhẹ, gây ra bất thường cục bộ trên mặt phẳng mục tiêu; ở mức độ nặng, có thể thay đổi quỹ đạo tiến hóa của văn minh đó, thậm chí gây ra sự sụp đổ luật pháp. Do đó, mục tiêu cốt lõi của quy tắc đi qua là &quot;kiểm soát tác động bên ngoài của hành động đi qua trong ngưỡng có thể chấp nhận được&quot;.</p><h2 id="_2-he-thong-phan-loai-giay-phep-đi-qua" tabindex="-1">2. Hệ thống Phân loại Giấy phép Đi qua <a class="header-anchor" href="#_2-he-thong-phan-loai-giay-phep-đi-qua" aria-label="Permalink to &quot;2. Hệ thống Phân loại Giấy phép Đi qua&quot;">​</a></h2><p>Hengyuanzhou thực hiện hệ thống phân loại giấy phép đi qua mặt phẳng, chia giấy phép thành bốn cấp độ theo mục đích đi qua, loại mặt phẳng mục tiêu và năng lực của người đi qua:</p><table tabindex="0"><thead><tr><th>Cấp độ Giấy phép</th><th>Kịch bản Áp dụng</th><th>Cơ quan Phê duyệt</th><th>Thời hạn</th><th>Điều kiện Bổ sung</th></tr></thead><tbody><tr><td>Cấp A (Quan sát Khảo cổ)</td><td>Khảo cổ thuần túy quan sát, không có tiếp xúc vật lý nào</td><td>Cục Quản lý Mặt phẳng</td><td>Nhiệm vụ đơn lẻ</td><td>Phải sử dụng sơ đồ gương sao chép + không gian cách ly</td></tr><tr><td>Cấp B (Trao đổi Học thuật)</td><td>Trao đổi kiến thức hạn chế với văn minh mặt phẳng mục tiêu</td><td>Cục Quản lý Mặt phẳng + Bộ Văn hóa</td><td>Tối đa một năm</td><td>Phải ký thỏa thuận không can thiệp lẫn nhau</td></tr><tr><td>Cấp C (Hợp tác Nguồn lực)</td><td>Hợp tác nguồn lực và công nghệ dưới tiền đề bình đẳng và cùng có lợi</td><td>Phê duyệt đặc biệt của Hội đồng Neo</td><td>Tối đa ba năm</td><td>Phải được sự đồng ý của văn minh mặt phẳng mục tiêu</td></tr><tr><td>Cấp D (Can thiệp Khẩn cấp)</td><td>Can thiệp nhân đạo khi mặt phẳng mục tiêu đối mặt với khủng hoảng cấp độ tuyệt chủng</td><td>Nghị quyết khẩn cấp của Hội đồng Neo</td><td>Trong thời gian khủng hoảng</td><td>Phải nộp báo cáo can thiệp đầy đủ sau đó</td></tr></tbody></table><p>Giấy phép đi qua bất kỳ cấp độ nào cũng cấm các hành động sau: cướp bóc năng lượng nguồn gốc của mặt phẳng mục tiêu, truyền bá tư tưởng của mặt phẳng自己 một cách cưỡng bức, thực hiện sửa đổi gen hoặc ý thức mà không có sự đồng ý, thiết lập căn cứ quân sự vĩnh viễn trên mặt phẳng mục tiêu, và bất kỳ hình thức thống trị thực dân nào.</p><h2 id="_3-yeu-cau-cong-nghe-va-nguong-nang-luong-đi-qua" tabindex="-1">3. Yêu cầu Công nghệ và Ngưỡng Năng lượng Đi qua <a class="header-anchor" href="#_3-yeu-cau-cong-nghe-va-nguong-nang-luong-đi-qua" aria-label="Permalink to &quot;3. Yêu cầu Công nghệ và Ngưỡng Năng lượng Đi qua&quot;">​</a></h2><p>Đi qua mặt phẳng đòi hỏi việc đáp ứng các điều kiện công nghệ nghiêm ngặt. Thứ nhất, người đi qua phải có tu luyện giai đoạn ba (Trạng thái Biến đổi Không gian) trở lên của &quot;hệ thống điều phối pháp lý không gian&quot;, hoặc mang theo phương tiện đi qua mặt phẳng đáp ứng tiêu chuẩn. Thứ hai, cả điểm bắt đầu và điểm kết thúc của việc đi qua đều phải có neo để hiệu chỉnh tọa độ; việc đi qua mù mà không có định vị neo bị nghiêm cấm nghiêm ngặt.</p><p>Mức tiêu thụ năng lượng trong quá trình đi qua tỷ lệ thuận với cường độ rào cản luật pháp của mặt phẳng mục tiêu. Hengyuanzhou đã thiết lập &quot;bảng ngưỡng năng lượng đi qua&quot; được tiêu chuẩn hóa, và năng lượng tối thiểu cần thiết để đi qua các loại mặt phẳng khác nhau là như sau:</p><ul><li>Mặt phẳng cơ bản vật chất: 1000 đơn vị năng lượng tiêu chuẩn</li><li>Mặt phẳng biểu hiện năng lượng: 5000 đơn vị năng lượng tiêu chuẩn</li><li>Mặt phẳng chủ đạo ý thức: 20000 đơn vị năng lượng tiêu chuẩn</li><li>Mặt phẳng luật pháp vỡ: 50000 đơn vị năng lượng tiêu chuẩn (và tỷ lệ thành công dưới 30%)</li><li>Mặt phẳng gần nguồn gốc: giá trị lý thuyết trên 100000, hiện tại không có hồ sơ thành công</li></ul><p>Năng lượng đi qua phải được mang theo bởi người đi qua hoặc phương tiện本身, bị cấm trích xuất năng lượng từ mặt phẳng mục tiêu cho quá trình đi qua. Quy định này nhằm mục đích ngăn chặn hành động đi qua gây ra cướp bóc năng lượng trên mặt phẳng mục tiêu.</p><h2 id="_4-phong-ngua-va-kiem-soat-o-nhiem-trong-qua-trinh-đi-qua" tabindex="-1">4. Phòng ngừa và Kiểm soát Ô nhiễm trong Quá trình Đi qua <a class="header-anchor" href="#_4-phong-ngua-va-kiem-soat-o-nhiem-trong-qua-trinh-đi-qua" aria-label="Permalink to &quot;4. Phòng ngừa và Kiểm soát Ô nhiễm trong Quá trình Đi qua&quot;">​</a></h2><p>Một trong những rủi ro lớn nhất của đi qua mặt phẳng là &quot;ô nhiễm liên mặt phẳng&quot;, bao gồm ô nhiễm sinh học (mang vi sinh vật từ mặt phẳng自己 vào mặt phẳng mục tiêu), ô nhiễm năng lượng (tàn dư năng lượng của mặt phẳng自己 can thiệp vào luật pháp của mặt phẳng mục tiêu) và ô nhiễm ý thức (biến động ý thức của người đi qua ảnh hưởng đến lĩnh vực ý thức của mặt phẳng mục tiêu).</p><p>Để phòng ngừa và kiểm soát ô nhiễm, tất cả người đi qua phải hoàn thành &quot;chương trình thanh lọc ba cấp độ&quot; trước khi khởi hành:</p><ol><li><strong>Thanh lọc sinh học</strong>: Thực hiện sàng lọc và loại bỏ vi sinh vật trong 72 giờ trong không gian cách ly, đảm bảo không mang bất kỳ mầm bệnh nào từ mặt phẳng自己</li><li><strong>Thanh lọc năng lượng</strong>: Điều chỉnh tần số năng lượng của người đi qua đến phạm vi tương thích với mặt phẳng mục tiêu thông qua thiết bị hiệu chỉnh neo, giảm phản ứng từ chối năng lượng</li><li><strong>Thanh lọc ý thức</strong>: Thực hiện đào tạo chặn ý thức, đảm bảo trong quá trình đi qua không chủ động giải phóng biến động ý chí có thể can thiệp vào lĩnh vực ý thức của mặt phẳng mục tiêu</li></ol><p>Ngoài ra, phạm vi hoạt động của người đi qua trên mặt phẳng mục tiêu bị giới hạn nghiêm ngặt trong &quot;vùng được xác định bởi giấy phép đi qua&quot;, việc lan tỏa không được phép bị cấm. Sau khi trở về mặt phẳng自己, người đi qua phải lại trải qua quan sát cách ly trong thời gian không ít hơn 30 ngày được quy đổi theo tốc độ dòng chảy thời gian của mặt phẳng mục tiêu.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Quy tắc đi qua mặt phẳng là tuyến phòng thủ an toàn đầu tiên của tương tác liên mặt phẳng. Thông qua ba cơ chế — phân loại giấy phép, ngưỡng công nghệ và phòng ngừa ô nhiễm — đảm bảo rằng hành động đi qua luôn hoạt động trên đường ray &quot;tác động thấp, có thể truy vết, có thể trách nhiệm&quot;. Mục tiêu cuối cùng của quy tắc không phải là hạn chế trao đổi giữa các văn minh, mà là làm cho trao đổi xảy ra theo cách cộng sinh, thay vì theo cách cướp bóc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>80-Lý thuyết và Phân loại Mặt phẳng</li><li>88-Hướng dẫn Đạo đức Liên mặt phẳng</li><li>62-Triển khai Công nghệ Pháp lý Không gian</li></ul>',23)])])}const e=t(a,[["render",c]]);export{q as __pageData,e as default};
